const megaSheet = $('Leer Mega en Clientes TotalTv').first().json;
const megaIdSheet = $('Leer MegaID en Chatwoot').first().json;

// 1. Indexar clientes ya registrados en MegaID de Chatwoot
const existingUsers = new Set();
const existingNames = new Set();
const existingIds = new Set();

const megaIdRows = megaIdSheet.values || [];
if (megaIdRows.length > 0) {
  const idHeaders = megaIdRows[0].map(h => String(h || '').trim());
  const uIdx = idHeaders.findIndex(h => /^usuario$/i.test(h) || /^user$/i.test(h));
  const nIdx = idHeaders.findIndex(h => /^nombre$/i.test(h) || /^name$/i.test(h));
  const aIdx = idHeaders.findIndex(h => /^apellido$/i.test(h) || /^last/i.test(h));
  const mIdIdx = idHeaders.findIndex(h => /id.*mega|mega.*id/i.test(h));

  for (let i = 1; i < megaIdRows.length; i++) {
    const r = megaIdRows[i];
    const u = uIdx !== -1 && r[uIdx] ? String(r[uIdx]).trim().toLowerCase() : '';
    const n = nIdx !== -1 && r[nIdx] ? String(r[nIdx]).trim().toLowerCase() : '';
    const a = aIdx !== -1 && r[aIdx] ? String(r[aIdx]).trim().toLowerCase() : '';
    const mid = mIdIdx !== -1 && r[mIdIdx] ? String(r[mIdIdx]).trim() : '';

    if (u) existingUsers.add(u);
    if (n || a) existingNames.add(`${n} ${a}`.replace(/\s+/g, ' ').trim());
    if (mid) existingIds.add(mid);
  }
}

// 2. Analizar clientes de la hoja Mega en Clientes TotalTv
const megaRows = megaSheet.values || [];
if (megaRows.length <= 1) {
  return [{ json: { hasNewClients: false, newClientsCount: 0, message: 'No data in Mega sheet', rowsToAppend: [] } }];
}

const headers = megaRows[0].map(h => String(h || '').trim());
const colIdx = {
  nombre: headers.findIndex(h => /^nombre$/i.test(h) || /^name$/i.test(h)),
  apellido: headers.findIndex(h => /^apellido$/i.test(h) || /^last\s*name$/i.test(h)),
  usuario: headers.findIndex(h => /^usuario$/i.test(h) || /^user$/i.test(h) || /^username$/i.test(h)),
  clave: headers.findIndex(h => /^clave$/i.test(h) || /^password$/i.test(h) || /^pass$/i.test(h)),
  telefono: headers.findIndex(h => /tel|cel|phone|movil/i.test(h)),
  dns: headers.findIndex(h => /^dns$/i.test(h) && !/smarter/i.test(h)),
  dnsSmarters: headers.findIndex(h => /dns.*smarter|smarter.*dns/i.test(h))
};

const newClients = [];

for (let i = 1; i < megaRows.length; i++) {
  const row = megaRows[i];
  const nombre = colIdx.nombre !== -1 ? String(row[colIdx.nombre] || '').trim() : '';
  const apellido = colIdx.apellido !== -1 ? String(row[colIdx.apellido] || '').trim() : '';
  const usuario = colIdx.usuario !== -1 ? String(row[colIdx.usuario] || '').trim() : '';
  const clave = colIdx.clave !== -1 ? String(row[colIdx.clave] || '').trim() : '';
  const telefono = colIdx.telefono !== -1 ? String(row[colIdx.telefono] || '').trim() : '';
  const sheetDns = colIdx.dns !== -1 ? String(row[colIdx.dns] || '').trim() : '';
  const sheetDnsSmarters = colIdx.dnsSmarters !== -1 ? String(row[colIdx.dnsSmarters] || '').trim() : '';

  if (!nombre && !apellido && !usuario) continue;

  const uLower = usuario.toLowerCase();
  const fullNameLower = `${nombre} ${apellido}`.replace(/\s+/g, ' ').trim().toLowerCase();

  // Verificar si ya existe en MegaID
  const existsByUser = uLower && existingUsers.has(uLower);
  const existsByName = fullNameLower && existingNames.has(fullNameLower);

  if (!existsByUser && !existsByName) {
    newClients.push({
      nombre,
      apellido,
      usuario,
      clave,
      telefono,
      sheetDns,
      sheetDnsSmarters,
      fullNameLower
    });
  }
}

if (newClients.length === 0) {
  return [{
    json: {
      hasNewClients: false,
      newClientsCount: 0,
      totalMegaRows: megaRows.length - 1,
      totalMegaIdRows: megaIdRows.length - 1,
      message: 'Todos los clientes ya estan registrados en MegaID. No hay nuevos clientes.',
      rowsToAppend: []
    }
  }];
}

// 3. Consultar Mega OTT API para obtener suscripciones
const MEGA_API_KEY = '1655|Uk2GI2EUH0v8NIcUFjGwLeKLlp14bVmEi2rcGSuJ48ec8236';
let allSubs = [];
let page = 1;
let lastPage = 1;

while (page <= lastPage) {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://megaott.net/api/v1/subscriptions?per_page=100&page=${page}`,
    headers: {
      'Authorization': `Bearer ${MEGA_API_KEY}`,
      'Accept': 'application/json',
      'User-Agent': 'Mozilla/5.0'
    },
    json: true
  });

  const subs = resp.data || [];
  allSubs = allSubs.concat(subs);
  lastPage = resp.last_page || resp.meta?.last_page || page;
  if (page >= lastPage || subs.length === 0) break;
  page++;
}

// Indexar suscripciones de Mega OTT API
const subByUsername = new Map();
const subByNote = new Map();
const subByPhone = new Map();

for (const sub of allSubs) {
  if (sub.username) {
    subByUsername.set(String(sub.username).trim().toLowerCase(), sub);
  }
  if (sub.note) {
    const normNote = String(sub.note).toLowerCase().replace(/\s+/g, ' ').trim();
    if (normNote.length > 2) {
      subByNote.set(normNote, sub);
    }
  }
  if (sub.customer_phone || sub.whatsapp_telegram) {
    const rawPhone = sub.customer_phone || sub.whatsapp_telegram;
    const phoneDigits = String(rawPhone).replace(/\D/g, '');
    if (phoneDigits.length >= 7 && phoneDigits !== '13059861096' && phoneDigits !== '573009476271') {
      subByPhone.set(phoneDigits, sub);
    }
  }
}

// 4. Cruzar cada nuevo cliente con la API
const rowsToAppend = [];
let matchedCount = 0;
let unmatchedCount = 0;

for (const client of newClients) {
  let matchedSub = null;

  if (client.usuario) {
    matchedSub = subByUsername.get(client.usuario.toLowerCase());
  }
  if (!matchedSub && client.fullNameLower && client.fullNameLower.length > 2) {
    matchedSub = subByNote.get(client.fullNameLower);
  }
  if (!matchedSub && client.telefono) {
    const pDigits = client.telefono.replace(/\D/g, '');
    if (pDigits.length >= 7) {
      matchedSub = subByPhone.get(pDigits);
    }
  }

  let megaId = '';
  let finalDns = client.sheetDns;
  let finalDnsSmarters = client.sheetDnsSmarters;

  if (matchedSub) {
    matchedCount++;
    megaId = String(matchedSub.id || '');
    if (matchedSub.dns_link) finalDns = matchedSub.dns_link;
    else if (matchedSub.dns) finalDns = matchedSub.dns;

    if (matchedSub.dns_link_for_samsung_lg) finalDnsSmarters = matchedSub.dns_link_for_samsung_lg;
    else if (matchedSub.dns_smarters) finalDnsSmarters = matchedSub.dns_smarters;
  } else {
    unmatchedCount++;
  }

  rowsToAppend.push([
    client.nombre,
    client.apellido,
    client.usuario,
    client.clave,
    finalDns,
    finalDnsSmarters,
    megaId
  ]);
}

return [{
  json: {
    hasNewClients: true,
    newClientsCount: rowsToAppend.length,
    matchedCount,
    unmatchedCount,
    totalSubsFetched: allSubs.length,
    totalMegaRows: megaRows.length - 1,
    totalMegaIdRows: megaIdRows.length - 1,
    rowsToAppend
  }
}];

const proc = $('Identificar Nuevos Clientes y Cruzar con Mega OTT').first().json;
let appendResult = null;

if (proc.hasNewClients) {
  try {
    appendResult = $('Agregar Nuevos Clientes en MegaID').first().json;
  } catch (e) {
    appendResult = { error: e.message };
  }
}

return [{
  json: {
    status: 'success',
    timestamp: new Date().toISOString(),
    workflow: 'Cron - Sincronizar Nuevos Clientes Mega a MegaID (Lunes 4AM)',
    hasNewClients: proc.hasNewClients,
    newClientsCount: proc.newClientsCount,
    matchedCount: proc.matchedCount || 0,
    unmatchedCount: proc.unmatchedCount || 0,
    totalMegaRows: proc.totalMegaRows,
    totalMegaIdRows: proc.totalMegaIdRows,
    appendDetails: appendResult,
    summary: proc.hasNewClients 
      ? `Se agregaron ${proc.newClientsCount} clientes nuevos a la hoja MegaID de Chatwoot.` 
      : 'No habian clientes nuevos por agregar.'
  }
}];
